import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_sub_bias_tanh_kernel(const float* input, const float* bias, float* output, 
                                           int num_channels, int height, int width, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    int hw = height * width;
    int c = (idx / hw) % num_channels;
    output[idx] = tanhf(input[idx] - bias[c]);
}

torch::Tensor fused_sub_bias_tanh_cuda(torch::Tensor input, torch::Tensor bias) {
    auto num_channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);
    auto output = torch::empty_like(input);
    int total_elements = input.numel();

    const int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    fused_sub_bias_tanh_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        num_channels,
        height,
        width,
        total_elements
    );

    return output;
}
"""

fused_ops_cpp = "torch::Tensor fused_sub_bias_tanh_cuda(torch::Tensor input, torch::Tensor bias);"

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp,
    cuda_sources=fused_ops_source,
    functions=["fused_sub_bias_tanh_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, bias_shape, stride=2, padding=1, output_padding=1):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, 
                                                stride=stride, padding=padding, 
                                                output_padding=output_padding)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_ops.fused_sub_bias_tanh_cuda(x, self.bias)
        return x
